source='''def transform(grid):
    src = [row[:] for row in grid]
    out = [row[:] for row in grid]
    h, w = len(src), len(src[0])

    # A horizontal 5-bar can carry a perpendicular color strip at either end.
    for r in range(h):
        c = 0
        while c < w:
            if src[r][c] != 5 or (c and src[r][c - 1] == 5):
                c += 1
                continue
            end = c
            while end + 1 < w and src[r][end + 1] == 5:
                end += 1
            if end > c:
                for anchor in (c, end):
                    for dr in (-1, 1):
                        rr = r + dr
                        strip = []
                        while 0 <= rr < h and src[rr][anchor] not in (0, 5):
                            strip.append(src[rr][anchor])
                            rr += dr
                        for offset, color in enumerate(strip, 1):
                            rr = r + dr * offset
                            for cc in range(c, end + 1):
                                out[rr][cc] = color
            c = end + 1

    # A vertical 5-bar copies each adjacent colored row-pattern along its length.
    for c in range(w):
        r = 0
        while r < h:
            if src[r][c] != 5 or (r and src[r - 1][c] == 5):
                r += 1
                continue
            end = r
            while end + 1 < h and src[end + 1][c] == 5:
                end += 1
            if end > r:
                for side in (-1, 1):
                    nc = c + side
                    if not 0 <= nc < w:
                        continue
                    rr = r
                    while rr <= end:
                        if src[rr][nc] in (0, 5):
                            rr += 1
                            continue
                        a = rr
                        while rr <= end and src[rr][nc] not in (0, 5):
                            rr += 1
                        b = rr - 1
                        pattern = []
                        for pr in range(a, b + 1):
                            row_pattern = []
                            cc = nc
                            while 0 <= cc < w and src[pr][cc] not in (0, 5):
                                row_pattern.append(src[pr][cc])
                                cc += side
                            pattern.append(row_pattern)
                        for tr in range(r, end + 1):
                            row_pattern = pattern[(tr - a) % len(pattern)]
                            for offset, color in enumerate(row_pattern, 1):
                                tc = c + side * offset
                                if 0 <= tc < w:
                                    out[tr][tc] = color
            r = end + 1
    return out
